function updateMissions(){homestead.done.explorer=['cave','falls','ruins','isles'].every(id=>exploration.places.includes(id));homestead.done.snow=exploration.places.includes('snow');homestead.done.sabre=exploration.seen.includes(8);homestead.done.mammoth=dinos.some(d=>d.index===7&&d.tame);homestead.done.nursery=exploration.cared>0;homestead.done.journal=exploration.seen.length===species.length;homestead.done.friend=dinos.some(d=>d.tame);homestead.done.name=dinos.some(d=>d.tame&&d.nickname);if(!homestead.done.home)homestead.done.home=homestead.pens.some(p=>penCells(p.x,p.z).every(c=>['fence','gate'].includes(blocks.get(key(c.x,height(c.x,c.z)+1,c.z))?.type))&&dinos.some(d=>d.tame&&!d.refuge&&d.order==='stay'&&insidePen(d.g.position,p)));}
function openFriends(){if(!playing)return;pause();const list=$('friendList');list.replaceChildren();const summary=document.createElement('p');summary.textContent=activeFriends(friendPopulation())+' / '+ACTIVE_COMPANIONS+' compagnons actifs · '+friendPopulation().filter(d=>d.tame&&d.refuge).length+' au refuge. Les œufs attendent si le groupe est complet.';list.append(summary);const friends=friendPopulation().filter(d=>d.tame);if(!friends.length)list.textContent='Ton premier ami t’attend ! Approche un dinosaure et offre-lui des baies.';for(const d of friends){const card=document.createElement('section');card.className='friend-card';if(abilityInfo[d.index]){const power=document.createElement('p');power.textContent=abilityInfo[d.index].icon+' '+abilityInfo[d.index].hint+(d.baby?' Disponible quand il sera adulte.':' Monte sur lui pour utiliser sa capacité.');card.append(power);}const title=document.createElement('h3');title.textContent=(d.baby?'🥚 ':'🦕 ')+(d.nickname||d.s.name);const info=document.createElement('p');info.textContent=(d.refuge?'🏡 Au refuge · ':'')+d.s.name+(d.happyUntil>time?' · Heureux 🤍':'')+' · '+(d.world?(d.world==='cave'?'Grotte des cristaux':'Savane africaine'):Math.round(d.g.position.distanceTo(pos))+' m')+' · '+(d.order==='stay'?'Reste sur place':'Te suit');const label=document.createElement('label');label.textContent='Son prénom';const input=document.createElement('input');input.maxLength=20;input.value=d.nickname||'';input.placeholder=d.s.name;label.append(input);const rename=document.createElement('button');rename.textContent='Enregistrer le prénom';rename.onclick=()=>{d.nickname=input.value.trim().slice(0,20);save();openFriends();};const order=document.createElement('button');order.textContent=d.order==='stay'?'🐾 Suis-moi':'🏡 Reste ici';order.onclick=()=>{d.order=d.order==='stay'?'follow':'stay';updateMissions();save();openFriends();};const pet=document.createElement('button');pet.textContent='🤍 Caresser';pet.disabled=d.refuge||(d.world?journeyWorld.active!==d.world||d.g.position.distanceTo(journeyWorld.pos)>5:d.g.position.distanceTo(pos)>5);order.disabled=!!d.refuge;const shelter=document.createElement('button');shelter.textContent=d.refuge?(d.world?'🐾 Revenir dans son habitat':'🐾 Revenir au camp'):'🏡 Confier au refuge';shelter.disabled=d.refuge&&!hasRoom(friendPopulation());shelter.onclick=()=>{const toRefuge=!d.refuge;if(!setRefuge(d,toRefuge,friendPopulation()))return;if(riding===d){riding=null;pos.set(0,ground(0,15)+1.65,15);}if(!toRefuge){if(d.world)journeyWorld.resetAnimal(d);else d.g.position.set(2,ground(2,13,true),13);d.order='stay';}save();openFriends();};pet.onclick=()=>{d.petUntil=(d.world?journeyWorld.clock:time)+3;sounds.dino(d.index,true);d.happyUntil=time+30;toast((d.nickname||d.s.name)+' est content !');resume();};if(d.baby){const care=document.createElement('p');care.textContent='Croissance : '+Math.floor(d.age/GROWTH_SECONDS*100)+' % · '+(d.fullness>0?'Ventre plein':'Une petite faim ! 🫐 Nourrir près du bébé');card.append(care);}const release=document.createElement('button');release.textContent='🌿 Libérer';release.onclick=()=>requestRelease(d);card.append(title,info,label,rename,order,pet,shelter,release);list.append(card);}if(!$('friendsMenu').open)$('friendsMenu').showModal();}
function openQuests(){if(!playing)return;pause();adventure.render();updateMissions();$('questList').replaceChildren();for(const m of missions){const card=document.createElement('section');card.className='friend-card';const h=document.createElement('h3');h.textContent=(homestead.claimed[m.id]?'✅ ':homestead.done[m.id]?'🎁 ':'○ ')+m.title;const p=document.createElement('p');p.textContent=m.hint;const b=document.createElement('button');b.textContent=homestead.claimed[m.id]?'Récompense reçue':homestead.done[m.id]?'Recevoir '+m.reward+' gemmes':'À faire · '+m.reward+' gemmes';b.disabled=!homestead.done[m.id]||homestead.claimed[m.id];b.onclick=()=>{claimMission(homestead,m.id,inv);save();openQuests();};card.append(h,p,b);$('questList').append(card);}if(!$('questsMenu').open)$('questsMenu').showModal();}
$('companions').onclick=openFriends;$('quests').onclick=openQuests;$('closefriends').onclick=resume;$('closequests').onclick=resume;

const mealVisuals=new T.Group();scene.add(mealVisuals);function refreshMeals(){for(const child of mealVisuals.children)child.dispose();mealVisuals.clear();for(const[k,stock]of Object.entries(homestead.feeders)){if(stock<=0||blocks.get(k)?.type!=='feeder')continue;const[x,y,z]=k.split(',').map(Number),mesh=new T.InstancedMesh(berryFruitGeo,berryFruitMat,stock);for(let i=0;i<stock;i++){dummy.position.set(x+(i%3-1)*.2,y-.12,z+(Math.floor(i/3)-.5)*.25);dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);}mealVisuals.add(mesh);}}refreshMeals();

let nextDiscovery=0;
function nestHint(e){const t=exploration.incubating[e.id];return t===undefined?'🪹 Nid découvert · 🤍 pour préparer l’éclosion':t>0?'🥚 Éclosion dans '+Math.ceil(t)+' s de jeu':'🐣 Prêt à éclore ! Appuie sur 🤍';}
function updateExploration(dt){tickIncubation(exploration,dt);secrets.update(time,pos);if(time<nextDiscovery)return;nextDiscovery=time+.5;
 for(const d of dinos)if(!d.refuge&&!d.foodAbsent&&!exploration.seen.includes(d.index)&&d.g.position.distanceTo(pos)<10&&!pathBlocked(pos,d.g.position)){exploration.seen.push(d.index);toast('📖 '+d.s.name+' découvert ! Sa fiche est dans ton carnet.');save();break;}
 for(const l of landmarks)if(!exploration.places.includes(l.id)&&Math.hypot(pos.x-l.x,pos.z-l.z)<9){exploration.places.push(l.id);toast(l.icon+' '+l.name+' découvert !');save();}
 for(const c of secrets.chests){c.g.visible=!exploration.treasures.includes(c.id)&&Math.hypot(pos.x-c.x,pos.z-c.z)<140;if(c.g.visible&&Math.hypot(pos.x-c.x,pos.z-c.z)<1.8&&Math.abs(pos.y-c.g.position.y-1.65)<2&&!pathBlocked(pos,c.g.position)){const n=collectSecret(exploration,c.id,inv);if(n){c.g.visible=false;toast('Trésor secret ! +'+n+' gemmes 💎');sounds.play('treasure');save();}}}
}
function openJournal(){if(!playing)return;pause();journeyWorld?.renderJournal();const pictures=dinosaurPortraits();$('ecologyStats').textContent='🌿 '+dinos.filter(d=>!d.tame&&!d.foodAbsent).length+' animaux terrestres sauvages · '+ecology.meals+' repas observés · '+activeFriends(friendPopulation())+' compagnons sur l’île.';$('journalProgress').textContent=exploration.seen.length+' / '+species.length+' espèces · '+exploration.places.length+' / '+landmarks.length+' lieux · '+exploration.treasures.length+' / '+hiddenTreasures.length+' trésors';const grid=$('speciesGrid');grid.replaceChildren();species.forEach((s,i)=>{const known=exploration.seen.includes(i),card=document.createElement('article');card.className='dino-entry'+(known?'':' unknown');if(pictures[i]){const img=document.createElement('img');img.src=pictures[i];img.alt=known?s.name:'Silhouette d’une espèce à découvrir';img.width=240;img.height=180;card.append(img);}const h=document.createElement('h3');h.textContent=known?s.name:'Espèce inconnue';const p=document.createElement('p');p.textContent=known?entries[i][2]:'Approche un animal pour révéler sa fiche.';const detail=document.createElement('p');detail.className='entry-detail';detail.textContent='🧭 '+entries[i][0];card.append(h,p,detail);if(known){const status=document.createElement('p');status.className='entry-detail';status.textContent='🫐 '+entries[i][1]+' pour devenir amis · '+(dinos.some(d=>d.index===i&&d.tame)?'🤍 Ami':'À apprivoiser')+' · '+(s.mammal?'Mammifère':found.includes(i)?'🥚 Bébé découvert':'Œuf à découvrir');card.append(status);}grid.append(card);});
 const places=$('placesList');places.replaceChildren();for(const p of [rockPassage,currentZone]){const entry=document.createElement('section');entry.className='friend-card';const title=document.createElement('h3');title.textContent=(p.id==='horns'?'🪨 ':'🌊 ')+p.name;const info=document.createElement('p');info.textContent=(p.id==='horns'?'Monte un tricératops adulte et brise les rochers dorés à l’entrée.':'Monte un spinosaure adulte pour traverser le courant, puis plonge vers le coffre.')+' 🧭 '+compass(Math.atan2(pos.x-p.x,pos.z-p.z))+' · '+Math.round(Math.hypot(pos.x-p.x,pos.z-p.z))+' m'+(abilities.treasures.includes(p.id)?' · Trésor trouvé ✓':'');entry.append(title,info);places.append(entry);}for(const zone of diveZones){const card=document.createElement('section');card.className='friend-card';const title=document.createElement('h3');title.textContent='🤿 '+zone.name;const info=document.createElement('p');info.textContent='Bouée turquoise · '+compass(Math.atan2(pos.x-zone.x,pos.z-zone.z))+' · '+Math.round(Math.hypot(pos.x-zone.x,pos.z-zone.z))+' m. '+(zone.id==='ruins'?'Un trésor se cache entre les colonnes englouties.':'Poissons paisibles et crocodile à observer.');card.append(title,info);places.append(card);}const marineInfo=document.createElement('p');marineInfo.textContent='🐠 Animaux marins découverts : '+(marine.state.seen.map(id=>marineSpecies[id].name).join(' · ')||'aucun pour le moment')+' · Trésor marin : '+(marine.state.treasure?'trouvé ✓':'à découvrir');places.append(marineInfo);for(const l of landmarks){const card=document.createElement('section');card.className='friend-card';const h=document.createElement('h3');h.textContent=l.icon+' '+l.name+(exploration.places.includes(l.id)?' ✓':'');const p=document.createElement('p');p.textContent=l.hint;const direction=document.createElement('p');direction.className='entry-detail';direction.textContent='🧭 '+compass(Math.atan2(pos.x-l.x,pos.z-l.z))+' · '+Math.round(Math.hypot(pos.x-l.x,pos.z-l.z))+' m';card.append(h,p,direction);places.append(card);}const nests=$('nestProgress');nests.textContent=Object.keys(exploration.incubating).length?Object.entries(exploration.incubating).map(([id,t])=>{const e=eggs.find(e=>e.id===id);return (e?biome(e.x,e.z):'Nid')+' : '+(t>0?Math.ceil(t)+' s de jeu restantes':'prêt à éclore !');}).join(' · '):'Explore pour trouver un nid. Prépare-le avec un nid fabriqué à l’atelier, puis reviens après 45 secondes de jeu.';if(!$('journalMenu').open)$('journalMenu').showModal();}
$('journal').onclick=openJournal;$('closejournal').onclick=resume;

const boutique=createShop({state:wardrobe,inv,dinos,progress:()=>({marine:marine.state.treasure,snow:exploration.places.includes('snow'),expeditions:expeditions.done.length===3}),save,pause,resume,sound:n=>sounds.play(n),atCamp:()=>playing&&!journeyWorld?.active&&nearStand(campShop),message:toast});

const adventure=createExpeditions({state:expeditions,inv,wardrobe,scene,ground:(x,z)=>ground(x,z,true),clearGround:ground,blocked:pathBlocked,save,resume,message:toast,sound:n=>sounds.play(n)});
$('expeditionAct').onclick=()=>{if(playing&&!paused)adventure.act(pos);};

abilityWorld=createAbilityWorld({scene,state:abilities,ground,blocked:(a,b)=>pathBlocked(a,b,true),inv,save,message:toast,sound:n=>sounds.play(n)});
function useAbility(){if(!playing||paused)return;if(journeyWorld?.active){journeyWorld.fire();return;}if(!riding)return;if(canUseAbility(riding,0)){abilityWorld.crush(riding,pos,yaw);return;}if(canUseAbility(riding,9)){if(activateSprint(sprint,riding,time)){sounds.play('jump');toast('💨 C’est parti ! Cours avec le joystick.');}else toast('Ton raptor reprend son souffle : '+Math.ceil(sprint.ready-time)+' s');return;}if(canUseAbility(riding,4)){if(!diveZone(pos.x,pos.z)){toast('🌊 Ton spinosaure nage vite automatiquement. Rejoins une bouée pour plonger.');return;}$('dive').click();return;}if(canUseAbility(riding,5))jump();}
function updateAbilityButton(){if(Math.hypot(pos.x-currentZone.x,pos.z-currentZone.z)<8&&pos.y<2&&!canUseAbility(riding,4))$('hint').textContent='🌊 Courant fort ! Monte un spinosaure adulte pour le traverser.';if(!abilities.opened&&Math.hypot(pos.x-rockPassage.x,pos.z-rockPassage.z)<8)$('hint').textContent=canUseAbility(riding,0)?'🪨 Regarde les rochers dorés, puis appuie sur Briser !':'🪨 Ce passage s’ouvre avec un tricératops adulte.';const info=riding&&!riding.baby&&abilityInfo[riding.index],button=$('ability');button.hidden=!info;if(!info){sprint.until=0;return;}let label=info.name;button.disabled=false;if(riding.index===9){const active=isSprinting(sprint,riding,time);label=active?'Sprint ! '+Math.ceil(sprint.until-time)+' s':time<sprint.ready?'Repos '+Math.ceil(sprint.ready-time)+' s':'Sprint';button.disabled=time<sprint.ready;}if(riding.index===4)label=descending?'Remonter':diveZone(pos.x,pos.z)?'Plonger':'Nager vite';const html=info.icon+'<small>'+label+'</small>';if(button.innerHTML!==html)button.innerHTML=html;button.setAttribute('aria-label',riding.s.name+' : '+label);}
$('ability').onclick=useAbility;

let releaseTarget=null;
function requestRelease(d){releaseTarget=d;$('releaseText').textContent='Libérer '+(d.nickname||d.s.name)+' ? Il retourne à la vie sauvage et quitte tes amis. Tu pourras l’apprivoiser à nouveau avec des baies. Pour le garder, utilise plutôt le refuge.';$('releaseMenu').showModal();$('cancelRelease').focus();}
$('cancelRelease').onclick=()=>{$('releaseMenu').close();releaseTarget=null;};
$('releaseMenu').addEventListener('cancel',()=>{releaseTarget=null;});
$('confirmRelease').onclick=()=>{const d=releaseTarget;if(!d?.tame)return;const before={...d},visible=d.g.visible,oldRide=riding,oldPos=pos.clone(),oldLook=wardrobe.looks[d.id],oldSprint=sprint.until,oldDescending=descending,oldFlight=flightBoostUntil;if(!releaseCompanion(d,true))return;if(riding===d){riding=null;descending=false;sprint.until=0;flightBoostUntil=0;pos.set(0,ground(0,15)+1.65,15);}d.retreatUntil=time+15;delete wardrobe.looks[d.id];if(!save()){Object.assign(d,before);d.g.visible=visible;riding=oldRide;pos.copy(oldPos);sprint.until=oldSprint;descending=oldDescending;flightBoostUntil=oldFlight;if(oldLook)wardrobe.looks[d.id]=oldLook;$('releaseText').textContent='La sauvegarde est indisponible. Ton compagnon reste avec toi. Vérifie le stockage du navigateur avant de réessayer.';return;}if(!d.world)applyLook(d.g,d.index,{});$('releaseMenu').close();releaseTarget=null;toast('🌿 Ton compagnon retrouve la liberté. Une place est disponible !');openFriends();};
const cameraRay=new T.Raycaster(),avatarModel=createPlayerAvatar(playerStyle),playerAvatar=avatarModel.g;scene.add(playerAvatar);
function refreshPlayer(){avatarModel.refresh();$('cameraView').textContent=playerStyle.thirdPerson?'👁️ Vue première personne':'👤 Vue troisième personne';$('cameraView').setAttribute('aria-pressed',String(playerStyle.thirdPerson));}refreshPlayer();
$('cameraView').onclick=()=>{if(!playing||paused)return;playerStyle.thirdPerson=!playerStyle.thirdPerson;refreshPlayer();save();};
const campShop={x:-6,z:12},campDressing=campShop;
shopStructure=createShopBuilding({scene,x:campShop.x,z:campShop.z,y:ground(campShop.x,campShop.z,true)});
function nearStand(){return !!shopStructure?.aimedAt(pos,yaw,pitch,localTargets(pos.x,pos.z),riding);}
function openPlayer(){if(playing&&!paused)unifiedStore?.open();}

journeyWorld=createJourneyWorld({island:scene,ground,inv,saved:saved?.journey,save,message:toast,sound:n=>sounds.play(n),pause,resume,hasRoom:()=>hasRoom(friendPopulation()),requestRelease,avatar:playerAvatar,style:playerStyle});
$('journeyTravel').onclick=()=>{if(!playing||paused)return;journeyWorld.travel(pos);};
$('journeyExit').onclick=()=>{if(!playing||paused)return;journeyWorld.leave();};
$('journeyFire').onclick=()=>{if(playing&&!paused)journeyWorld.fire();};
const originalRefreshPlayer=refreshPlayer;refreshPlayer=function(){originalRefreshPlayer();journeyWorld?.refreshAvatar();};

createSaveTransfer({save,message:toast});

const miloPanel=createMiloPanel({state:miloState,inv,save,message:toast,progress:()=>({friends:friendPopulation().filter(d=>d.tame).length,furniture:[...blocks.values()].filter(b=>Math.hypot(b.x,b.z)<24&&edits[key(b.x,b.y,b.z)]===b.type).map(b=>b.type),...journeyWorld.serialize()})});
unifiedStore=createUnifiedStore({miloPanel,boutique,state:playerStyle,inv,save,refresh:refreshPlayer,progress:()=>({crystal:!!journeyWorld?.serialize().treasure,safari:!!journeyWorld?.serialize().visited.africa}),message:toast});
const outfitBoxes=outfitCaches.map(c=>{const group=new T.Group();box(group,0,.4,0,.8,.8,.8,0x9b81c7);box(group,0,.4,0,.85,.16,.85,0xffdd83);group.position.set(c.x,ground(c.x,c.z,true),c.z);scene.add(group);return {...c,g:group};});
function updateOutfitCaches(){for(const cache of outfitBoxes){cache.g.visible=!playerStyle.owned.includes(cache.id);if(cache.g.visible&&cache.g.position.distanceTo(pos)<2.5&&!pathBlocked(pos,cache.g.position)){unlockOutfit(playerStyle,cache.id);cache.g.visible=false;save();toast('👕 '+cache.name+' trouvé ! Retrouve-le dans la boutique.');}}}
